begin;
create extension if not exists pgtap with schema extensions;grant usage on schema extensions to cuevo_api;set local search_path=extensions,pg_catalog;select no_plan();
create temporary table maintenance_fixture(room uuid,post uuid,report uuid,announcement uuid);grant select,insert,update on maintenance_fixture to cuevo_api;
set local role cuevo_api;select set_config('app.school_id','10000000-0000-4000-8000-000000000001',true);select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
insert into maintenance_fixture(room)values((internal.community_command('room.create',null,'{"classId":"30000000-0000-4000-8000-000000000001","name":"Controlled lifecycle group","type":"GROUP","memberIds":["20000000-0000-4000-8000-000000000012"]}','maintenance-group-create',repeat('a',64),'maintenance-test')->>'id')::uuid);
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);update maintenance_fixture set post=(internal.community_command('post.create',room,'{"body":"Original group post","replyToId":null}','maintenance-post',repeat('b',64),'maintenance-test')->>'id')::uuid;update maintenance_fixture set report=(internal.community_command('report.create',post,'{"reason":"Please review this wording"}','maintenance-report',repeat('c',64),'maintenance-test')->>'id')::uuid;
select throws_ok($$select internal.community_maintenance_command('group',(select room from maintenance_fixture),'{"name":"Attempted closure","state":"CLOSED","expectedRevision":1,"reason":"Learner attempt","confirmChange":true}','maintenance-student-close',repeat('d',64),'maintenance-test')$$,'42501',null,'learner cannot change group lifecycle');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select internal.community_maintenance_command('report',(select report from maintenance_fixture),'{"outcome":"RESOLVED","expectedRevision":0,"reason":"Teacher reviewed exact source","confirmReview":true}','maintenance-report-review',repeat('e',64),'maintenance-test')is not null as reviewed;
select internal.community_maintenance_command('group',(select room from maintenance_fixture),'{"name":"Closed current group","state":"CLOSED","expectedRevision":1,"reason":"Teacher closes group","confirmChange":true}','maintenance-close',repeat('f',64),'maintenance-test')is not null as closed;
select lives_ok($$select internal.community_maintenance_command('group',(select room from maintenance_fixture),'{"name":"Closed current group","state":"CLOSED","expectedRevision":1,"reason":"Teacher closes group","confirmChange":true}','maintenance-close',repeat('f',64),'maintenance-test')$$,'original group closure key reconciles singular source');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000012',true);
select lives_ok($$select internal.community_list('posts',(select room from maintenance_fixture),'{"limit":100}')$$,'current member reads closed permitted history');
select throws_ok($$select internal.community_command('post.create',(select room from maintenance_fixture),'{"body":"Cannot write closed room","replyToId":null}','maintenance-closed-post',repeat('a',64),'maintenance-test')$$,'42501',null,'closed group rejects new posts');
reset role;
select ok(not"authorization".community_room('10000000-0000-4000-8000-000000000001',(select room from maintenance_fixture),'20000000-0000-4000-8000-000000000012',false),'closed group cannot join live private channel');
set local role cuevo_api;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
update maintenance_fixture set announcement=(internal.community_command('announcement.create',null,'{"classId":"30000000-0000-4000-8000-000000000001","title":"Private original","body":"Original exact notice","parentVisible":false}','maintenance-announcement',repeat('b',64),'maintenance-test')->>'id')::uuid;
select internal.community_maintenance_command('announcement',(select announcement from maintenance_fixture),'{"title":"Approved correction","body":"Corrected current notice","parentVisible":true,"expectedRevision":1,"reason":"Teacher approved current notice","confirmPublication":true}','maintenance-correction',repeat('c',64),'maintenance-test')is not null as corrected;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select is(internal.read_community_announcement((select announcement from maintenance_fixture))->>'title','Approved correction','parent current source admits new approved revision');
select throws_ok($$select internal.community_announcement_revision_read((select announcement from maintenance_fixture),'{"expectedRevision":1}','maintenance-stale-read',repeat('d',64),'maintenance-test')$$,'42501',null,'raw exact read helper stays private to command owner');
select throws_ok($$select internal.community_command('notification.read',(select announcement from maintenance_fixture),'{"expectedRevision":1}','maintenance-stale-command',repeat('d',64),'maintenance-test')$$,'22023',null,'stale announcement read revision denied');
select internal.community_command('notification.read',(select announcement from maintenance_fixture),'{"expectedRevision":2}','maintenance-read2',repeat('e',64),'maintenance-test')is not null as read;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select internal.community_maintenance_command('announcement',(select announcement from maintenance_fixture),'{"title":"Another correction","body":"Another exact current notice","parentVisible":true,"expectedRevision":2,"reason":"Another reviewed update","confirmPublication":true}','maintenance-correction2',repeat('f',64),'maintenance-test')is not null as corrected_again;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);
select is(internal.read_community_announcement((select announcement from maintenance_fixture))->>'readAt',null,'earlier receipt cannot mark corrected announcement read');
select set_config('app.actor_id','20000000-0000-4000-8000-000000000004',true);
select internal.community_maintenance_command('withdraw',(select announcement from maintenance_fixture),'{"expectedRevision":3,"reason":"Teacher withdraws current source","confirmWithdrawal":true}','maintenance-withdraw',repeat('a',64),'maintenance-test')is not null as withdrawn;
select set_config('app.actor_id','20000000-0000-4000-8000-000000000072',true);select throws_ok($$select internal.read_community_announcement((select announcement from maintenance_fixture))$$,'42501',null,'withdrawal removes exact source read');
select ok(not has_table_privilege('authenticated','app.community_announcement_revisions','select'),'no browser raw announcement revision grant');select ok(not has_table_privilege('cuevo_api','app.community_group_revisions','select'),'no raw group source grant');reset role;select is((select count(*)from app.community_group_revisions where room_id=(select room from maintenance_fixture)),1::bigint,'group closure replay preserves singular immutable revision');select*from finish();rollback;

